const body = $input.first().json.body || {};
const TIMEFRAMES = ["As soon as possible", "Within a week", "Next week"];
const CONTACTS = ["WhatsApp", "Phone call", "Email"];
const text = (value) => String(value ?? "").trim();
const rawList = Array.isArray(body.appliance) ? body.appliance : text(body.appliance).split(",");
const seen = new Map();
for (const item of rawList) {
  const applianceName = text(item).replace(/["\\{}<>`]/g, "").replace(/\s+/g, " ").slice(0, 60);
  if (applianceName && !seen.has(applianceName.toLowerCase())) seen.set(applianceName.toLowerCase(), applianceName);
}
const appliances = [...seen.values()].slice(0, 12).sort((first, second) => first.localeCompare(second, undefined, { sensitivity: "base" }));
const name = text(body.name).slice(0, 100);
const phone = text(body.number).slice(0, 30);
const digits = phone.replace(/\D/g, "");
const contact = text(body.preferred_contact);
const timeframe = TIMEFRAMES.includes(text(body.timeframe)) ? text(body.timeframe) : "Not given";
const problem = text(body.problem).slice(0, 2000);
const submittedAt = text(body.submitted_at)
const reject = text(body.website) !== "" || !name || digits.length < 7 || !CONTACTS.includes(contact) || appliances.length === 0 || timeframe === "Not given" || !problem;
return [{ json: {
  reject,
  name,
  phone,
  email: text(body.email).slice(0, 200),
  preferred_contact: contact,
  appliance: appliances.length ? appliances.join(", ") : "Not given",
  problem,
  service_address: text(body.service_address).slice(0, 300),
  timeframe,
  submitted_at: submittedAt
}}];

