const form = $('Clean Data').first().json;
const repairTypes = new Set(['Cooling', 'Heating', 'Electrical', 'Water leak', 'Drainage', 'Noise / vibration', 'Controls / display', 'Installation / setup', 'Maintenance', 'Physical damage', 'Gas leak', 'Other / unknown']);
const urgencies = new Set(['High', 'Medium', 'Low']);
try {
  const output = $('Classify Request').first().json.output;
  const message = Array.isArray(output) ? output.find((item) => item.content) : null;
  let ai = message && message.content && message.content[0] ? message.content[0].text : null;
  if (typeof ai === 'string') ai = JSON.parse(ai);
  const valid = ai && repairTypes.has(ai.repair_type) && urgencies.has(ai.urgency) && typeof ai.needs_review === 'boolean' && typeof ai.review_reason === 'string' && typeof ai.summary === 'string' && typeof ai.acknowledgement === 'string' && (ai.needs_review ? ai.review_reason.trim().length > 0 : ai.review_reason === '');
  if (!valid) throw new Error('AI output failed validation');
  return { json: { name: form.name, phone: form.phone, email: form.email, preferred_contact: form.preferred_contact, appliance: form.appliance, service_address: form.service_address, problem: form.problem, timeframe: form.timeframe, submitted_at: form.submitted_at, repair_type: ai.repair_type, urgency: ai.urgency, needs_review: ai.needs_review ? 'Yes' : 'No', review_reason: ai.review_reason, summary: ai.summary, acknowledgement: ai.acknowledgement } };
} catch (error) {
  return { json: { name: form.name, phone: form.phone, email: form.email, preferred_contact: form.preferred_contact, appliance: form.appliance, service_address: form.service_address, problem: form.problem, timeframe: form.timeframe, submitted_at: form.submitted_at, repair_type: 'Other / unknown', urgency: 'Medium', needs_review: 'Yes', review_reason: 'AI classification failed validation; staff must review the original request.', summary: form.appliance + ' | Staff classification required', acknowledgement: '' } };
}
